#include <xc.h>
#define MAX 50

/* Devuelve un vector con los enteros comprendidos entre min y max */
void get_vector_discreto(int min, int max, int v[]) {
    int i;
    for (i = 0; i <= max - min; i++)
        v[i] = min + i;              // manejo tipo vector
}

void get_vector_discreto_p(int min, int max, int *v) {
    int i;
    for (i = 0; i <= max - min; i++)
        *(v + i) = min + i;          // manejo tipo puntero
}

void get_vector_discreto_pp(int min, int max, int *v) {
    int i;
    for (i = 0; i <= max - min; i++)
        *(v++) = min + i;            // puntero con postincremento
}

int main(void) {
    int vector[MAX];
    get_vector_discreto(1, 4, vector);   // vector = {1, 2, 3, 4}
}

