// ====== API del driver I2C que se da en los examenes ======
#define I2C400KHZ 1
#define I2C100KHZ 0

// Arranca el I2C1 y configura el BRG segun la velocidad del bus:
// I2C400KHZ -> 400 kb/s; otro valor -> 100 kb/s.
void I2C1Inicializa(int velocidad);

// Generan la condicion de start / repeated start / stop
// y esperan a que termine.
void I2C1GeneraStart(void);
void I2C1GeneraReStart(void);
void I2C1GeneraStop(void);

// Envia un byte al bus. Devuelve el ACK recibido: 0 OK, 1 error (NACK).
// El primer byte tras el start es la direccion: (dir << 1) para
// escribir, (dir << 1) | 1 para leer.
int I2C1EscribeByte(uint8_t dato);

// Lee un byte del bus y envia el ack indicado: 0 (ACK) si se va a
// seguir leyendo, 1 (NACK) en el ultimo byte. Devuelve el dato leido.
uint8_t I2C1LeeByte(int ack);

void I2C1Inicializa(int velocidad) {
    if (velocidad == 1) {             // 400 kb/s
        I2C1BRG = 4;
        I2C1CON = 0x8000;             // I2C ON, con control de slew rate
    } else {                          // 100 kb/s
        I2C1BRG = 23;
        I2C1CON = 0x8200;             // I2C ON, sin control de slew rate (DISSLW = 1)
    }
    IFS1bits.I2C1MIF = 0;             // Borra el flag por si acaso
}

void I2C1GeneraStart(void) {
    I2C1CONbits.SEN = 1;              // Genera la condición de start en el bus
    while (IFS1bits.I2C1MIF == 0) ;   // Espera el final de la condición
    IFS1bits.I2C1MIF = 0;             // Borra el flag
}

int I2C1EscribeByte(uint8_t dato) {
    I2C1TRN = dato;                   // Escribir en I2C1TRN inicia el envío
    while (IFS1bits.I2C1MIF == 0) ;   // Espera el final del envío (byte + ACK)
    IFS1bits.I2C1MIF = 0;             // Borra el flag
    return I2C1STATbits.ACKSTAT;      // ACK recibido: 0 = OK, 1 = NACK
}

void I2C1GeneraReStart(void) {
    I2C1CONbits.RSEN = 1;             // Genera la condición de repeated start
    while (IFS1bits.I2C1MIF == 0) ;   // Espera el final de la condición
    IFS1bits.I2C1MIF = 0;             // Borra el flag
}

void I2C1GeneraStop(void) {
    I2C1CONbits.PEN = 1;              // Genera la condición de stop
    while (IFS1bits.I2C1MIF == 0) ;   // Espera el final de la condición
    IFS1bits.I2C1MIF = 0;             // Borra el flag
}

uint8_t I2C1LeeByte(int ack) {
    uint8_t dato;

    // Recepción del byte
    I2C1CONbits.RCEN = 1;             // Activa la recepción (genera el reloj)
    while (IFS1bits.I2C1MIF == 0) ;   // Espera la llegada del dato
    IFS1bits.I2C1MIF = 0;             // Borra el flag
    dato = I2C1RCV;

    // Envío del bit de ACK (0 = quiero más datos; 1 = NACK, último byte)
    I2C1CONbits.ACKDT = ack & 1;      // Valor del ACK a enviar (bit 5 de I2C1CON)
    I2C1CONbits.ACKEN = 1;            // Inicia el envío del ACK
    while (IFS1bits.I2C1MIF == 0) ;   // Espera el final del envío
    IFS1bits.I2C1MIF = 0;             // Borra el flag

    return dato;
}

#define I2C400KHZ        1
#define I2C100KHZ        0
#define VCNL4010_ADDRESS 0x13   // Dirección de 7 bits
#define REGISTER_ID      0x81   // Registro con el ID del chip

int main(void) {
    // ...
    I2C1Inicializa(I2C400KHZ);
    // ...
}

int LeerChipIdVCNL4010(void) {
    int chip_id = 0;                  // 0 indica error de recepción

    I2C1GeneraStart();
    if (I2C1EscribeByte(VCNL4010_ADDRESS << 1) != 0) {        // NACK
        I2C1GeneraStop();             // Abortamos
        return chip_id;
    }
    if (I2C1EscribeByte(REGISTER_ID) != 0) {                  // NACK
        I2C1GeneraStop();             // Abortamos
        return chip_id;
    }
    I2C1GeneraReStart();              // Cambio de sentido sin soltar el bus
    if (I2C1EscribeByte((VCNL4010_ADDRESS << 1) | 1) != 0) {  // NACK
        I2C1GeneraStop();             // Abortamos
        return chip_id;
    }
    chip_id = I2C1LeeByte(1);         // NACK: ya no queremos más datos
    I2C1GeneraStop();
    return chip_id;
}

#define VCNL4010_ADDRESS 0x13   // Dirección de 7 bits
#define REGISTER_LIGHT   0x85   // Parte alta de la medida de luz

uint8_t LeerLuzVCNL4010(uint16_t *light) {
    uint8_t alto, bajo;

    *light = 0;
    I2C1GeneraStart();
    if (I2C1EscribeByte(VCNL4010_ADDRESS << 1) != 0) {        // NACK
        I2C1GeneraStop();             // Abortamos
        return 1;
    }
    if (I2C1EscribeByte(REGISTER_LIGHT) != 0) {               // NACK
        I2C1GeneraStop();             // Abortamos
        return 1;
    }
    I2C1GeneraReStart();
    if (I2C1EscribeByte((VCNL4010_ADDRESS << 1) | 1) != 0) {  // NACK
        I2C1GeneraStop();             // Abortamos
        return 1;
    }
    alto = I2C1LeeByte(0);   // ACK: el autoincremento pasa a 0x86
    bajo = I2C1LeeByte(1);   // NACK: último byte
    I2C1GeneraStop();

    *light = ((uint16_t)alto << 8) | bajo;
    return 0;
}

#define PIN_SS       10   // Puerto A (RA10): selección de esclavo
#define PIN_SCK      15   // Puerto B (RB15): SCK2 (fijo, no remapeable)
#define PIN_SDO       8   // Puerto A (RA8):  SDO2 (remapeable)
#define PIN_CMD_DAT   9   // Puerto C (RC9):  línea comando/dato del display

int InicializaRelojSPI2(int frecuencia);

void InicializarSPI2(int frec) {
    char dato;

    // 1. Pines como salidas digitales (se incluyen los del SPI por si acaso)
    TRISA &= ~((1 << PIN_SS) | (1 << PIN_SDO));
    TRISB &= ~(1 << PIN_SCK);
    TRISC &= ~(1 << PIN_CMD_DAT);
    ANSELA &= ~((1 << PIN_SS) | (1 << PIN_SDO));
    ANSELB &= ~(1 << PIN_SCK);
    ANSELC &= ~(1 << PIN_CMD_DAT);
    LATASET = 1 << PIN_SS;        // Arrancamos con SS desactivado (nivel alto)

    // 2. Remapeo de SDO2 (SCK2 está asignado a fuego a RB15)
    SYSKEY = 0xAA996655;          // Se desbloquean los registros
    SYSKEY = 0x556699AA;          // de configuración
    RPA8R  = 4;                   // SDO2 conectado a RA8
    SYSKEY = 0x1CA11CA1;          // Se vuelven a bloquear

    // 3. Módulo apagado y en estado de reset
    SPI2STAT = 0;
    SPI2CON  = 0;
    SPI2CON2 = 0;                 // Solo se usa en modos de audio
    dato = SPI2BUF;               // Vacía el buffer de recepción por si acaso

    // 4. Reloj SCK a la frecuencia pedida (con el módulo aún apagado)
    InicializaRelojSPI2(frec);

    // 5. Configuración: maestro, modo 0 (CPOL = 0, CPHA = 0)
    SPI2CONbits.MSTEN  = 1;       // Modo maestro
    SPI2CONbits.CKE    = 1;       // CPHA = 0 (¡CKE es el negado de CPHA!)
    SPI2CONbits.CKP    = 0;       // CPOL = 0 (ya estaba a 0; se deja explícito)
    SPI2CONbits.DISSDI = 1;       // SDI no se usa: el display solo recibe

    // 6. Encender y limpiar el overflow por si acaso
    SPI2CONbits.ON = 1;
    SPI2STATbits.SPIROV = 0;
}

#define SYSCLK 40000000L   // Reloj del sistema: 40 MHz
#define PBCLK   5000000L   // Reloj de periféricos: 5 MHz

int InicializaRelojSPI2(int frecuencia) {
    long fclkin;
    long brg;

    if (frecuencia <= 0 || frecuencia > SYSCLK / 2)
        return -1;                    // Imposible: más de 20 MHz (BRG = 0)

    if (frecuencia > 2500000) {       // > 2,5 MHz: reloj principal (40 MHz)
        SPI2CONbits.MCLKSEL = 1;      // (solo escribible con ON = 0)
        fclkin = SYSCLK;
    } else {                          // <= 2,5 MHz: reloj de periféricos
        SPI2CONbits.MCLKSEL = 0;
        fclkin = PBCLK;
    }

    brg = fclkin / (2 * frecuencia) - 1;
    if (brg > 8191)                   // No cabe en el registro (13 bits):
        return -1;                    // frecuencia demasiado pequeña

    SPI2BRG = brg;
    return 0;
}

void SPI_SendFrame(uint8_t dato) {
    LATACLR = 1 << PIN_SS;            // Activa SS (nivel bajo)
    while (SPI2STATbits.SPITBF) ;     // Espera hueco en el buffer de transmisión
    SPI2BUF = dato;                   // Carga el dato: comienza la transferencia
    while (SPI2STATbits.SPIRBE) ;     // Fin de transferencia = ha llegado un dato
    dato = SPI2BUF;                   // Se lee y descarta: si no, ¡overflow (SPIROV)
                                      // y el módulo se queda bloqueado!
    LATASET = 1 << PIN_SS;            // Desactiva SS para terminar la trama
}

uint8_t SPI_ReceiveFrame(void) {
    uint8_t dato;

    LATACLR = 1 << PIN_SS;            // Activa SS
    while (SPI2STATbits.SPITBF) ;     // Espera hueco en transmisión
    SPI2BUF = 0xFF;                   // Dato 'dummy': el maestro debe generar
                                      // el reloj para que el esclavo conteste
    while (SPI2STATbits.SPIRBE) ;     // Espera la llegada del dato
    dato = SPI2BUF;                   // Este sí nos interesa
    LATASET = 1 << PIN_SS;            // Desactiva SS
    return dato;
}
